contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(address logAddr) public {
        // Fresh contract: SetLogFile must succeed
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        bool revertedBefore;
        // Now initialize
        c.Initialized(); if (__ESBMC_reverted()) return;
        // After initialization: SetLogFile must revert
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedBefore = true; } else { revertedBefore = false; }
        assert(revertedBefore);
    }
}

